INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-6', 'seamark-freight-insights-6', 'Seamark Freight Industry Brief #6: GCC Cross-Border Reefer Truck', 'تقرير سيمارك للشحن التخصصي #6: نقل مبرد بري عبر الخليج', 'Key operational benchmarks and best practices from Seamark Freight in Khalifa Bin Salman Port.', 'أبرز المعايير التشغيلية وأفضل الممارسات من سيمارك للشحن في Khalifa Bin Salman Port.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"B2B freight forwarding and bonded warehousing operator handling customs clearance and GCC cross-border fleet distribution. Our GCC Cross-Border Reefer Truck division helps regional organizations scale predictably with transparent SLAs and bilingual reporting."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"شركة شحن وتخزين جمركي تدير التخليص الجمركي والتوزيع البري عبر دول الخليج. يساعد قسم نقل مبرد بري عبر الخليج المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير."}]}]}'::jsonb, '<p>B2B freight forwarding and bonded warehousing operator handling customs clearance and GCC cross-border fleet distribution.</p><p>Our GCC Cross-Border Reefer Truck division helps regional organizations scale predictably with transparent SLAs and bilingual reporting.</p>', '<p>شركة شحن وتخزين جمركي تدير التخليص الجمركي والتوزيع البري عبر دول الخليج.</p><p>يساعد قسم نقل مبرد بري عبر الخليج المؤسسات الإقليمية على النمو بثبات مع وضوح مستويات الخدمة والتقارير.</p>', 'logistics', '{"logistics","Khalifa Bin Salman Port","2026"}'::text[], 'Hana Yousef', 'draft', now() - interval '54 days', false, now() - interval '54 days', now()) ON CONFLICT (id) DO NOTHING;
